Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define F first
#define S second
#define MP make_pair
#define all(x) (x).begin(), (x).end()

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000000007;
const int INF = 2000000000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int S = MAXN - 2;
const int T = MAXN - 1;

template <typename T>
inline T sqr(T n) {
    return n * n;
}

struct MaxFlow {
    int to[MAXM], flow[MAXM], cap[MAXM], lastEdge;
    vector<int> g[MAXN];
    bool used[MAXN];

    MaxFlow() : lastEdge(0) {}

    void addEdge(int from, int to, int cap) {
        to[lastEdge] = to;
        flow[lastEdge] = 0;
        cap[lastEdge] = cap;
        g[from].push_back(lastEdge++);

        to[lastEdge] = from;
        flow[lastEdge] = 0;
        cap[lastEdge] = 0;
        g[to].push_back(lastEdge++);
    }

    bool dfs(int v, int T, int curFlow) {
        if (v == T) return true;
        used[v] = true;
        for (int idx : g[v]) {
            if (!used[to[idx]] && cap[idx] - flow[idx] >= curFlow && dfs(to[idx], T, curFlow)) {
                flow[idx] += curFlow;
                flow[idx ^ 1] -= curFlow;
                return true;
            }
        }
        return false;
    }

    int maxFlow(int S, int T) {
        int totalFlow = 0;
        int curFlow = 1 << 30;
        while (curFlow > 0) {
            if (dfs(S, T, curFlow))
                totalFlow += curFlow;
            else
                curFlow >>= 1;
            memset(used, false, sizeof used);
        }
        return totalFlow;
    }
};

MaxFlow mf;

int n, t;
char a[15][15], b[15][15];
int dist[15][15];
bool used[15][15];

bool ok(int x, int y) {
    return 0 <= x && x < n && 0 <= y && y < n && a[x][y] != 'Y' && a[x][y] != 'Z';
}

void bfsDeath(int x, int y) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            dist[i][j] = INF;
    queue<int> X, Y;
    dist[x][y] = 0;
    X.push(x);
    Y.push(y);
    while (!X.empty()) {
        int cx = X.front(); int cy = Y.front();
        X.pop(); Y.pop();
        for (int k = 0; k < 4; k++) {
            int tx = cx + dx[k], ty = cy + dy[k];
            if (ok(tx, ty) && dist[tx][ty] == INF) {
                dist[tx][ty] = dist[cx][cy] + 1;
                X.push(tx); Y.push(ty);
            }
        }
    }
}

void runBFS(int x, int y) {
    queue<int> X, Y, lev;
    memset(used, false, sizeof used);
    used[x][y] = true;
    X.push(x); Y.push(y); lev.push(0);
    while (!X.empty()) {
        int cx = X.front(); int cy = Y.front(); int levl = lev.front();
        X.pop(); Y.pop(); lev.pop();
        if (isdigit(b[cx][cy]) && b[cx][cy] != '0') {
            mf.addEdge(x * n + y, sqr(n) + 1 + cx * n + cy, INF);
        }
        if (levl >= t) continue;
        for (int k = 0; k < 4; k++) {
            int tx = cx + dx[k], ty = cy + dy[k];
            if (ok(tx, ty) && !used[tx][ty]) {
                if (dist[tx][ty] > levl + 1) {
                    X.push(tx); Y.push(ty);
                    lev.push(levl + 1);
                } else if (dist[tx][ty] > levl && isdigit(b[tx][ty]) && b[tx][ty] != '0') {
                    mf.addEdge(x * n + y, sqr(n) + 1 + tx * n + ty, INF);
                }
                used[tx][ty] = true;
            }
        }
    }
}

void build() {
    int px = -1, py = -1;
    for (int i = 0; i < n && px == -1; i++)
        for (int j = 0; j < n && px == -1; j++)
            if (a[i][j] == 'Z') { px = i; py = j; }
    bfsDeath(px, py);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(a[i][j]) && a[i][j] != '0')
                mf.addEdge(S, i * n + j, a[i][j] - '0');
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(b[i][j]) && b[i][j] != '0')
                mf.addEdge(i * n + j + sqr(n) + 1, T, b[i][j] - '0');
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (isdigit(a[i][j]) && a[i][j] != '0')
                runBFS(i, j);
}

int main() {
    scanf("%d %d", &n, &t);
    for (int i = 0; i < n; i++) scanf("%s", a[i]);
    for (int i = 0; i < n; i++) scanf("%s", b[i]);
    build();
    printf("%d\n", mf.maxFlow(S, T));
    return 0;
}
